def kthProduct(a, b, k):
    from bisect import bisect_left, bisect_right
    if len(a) > len(b):
        a, b = b, a
    m = len(b)

    def count(x):
        total = 0
        for v in a:
            if v > 0:
                total += bisect_right(b, x // v)
            elif v < 0:
                total += m - bisect_left(b, -(x // -v))
            elif x >= 0:
                total += m
        return total

    corners = (a[0] * b[0], a[0] * b[-1], a[-1] * b[0], a[-1] * b[-1])
    lo, hi = min(corners), max(corners)
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
